        sp=(shade[i][1]+shade[i+1][1])*0.5,
        tuck=i>n-9?0.30+0.70*(n-1-i)/8:1,      /* fades into the crimp */
        base=(22+d*70+sp*160)*tuck,
        r=Math.min(255,base*0.86),g=Math.min(255,base*0.92),b2=Math.min(255,base*1.08);
