  g.strokeStyle='rgba(58,44,16,.85)';g.lineWidth=1.1;
  g.beginPath();
  g.moveTo(x,y+h*0.30);g.lineTo(x+w*0.30,y+h*0.30);
  g.moveTo(x+w*0.70,y+h*0.30);g.lineTo(x+w,y+h*0.30);
  g.moveTo(x,y+h*0.70);g.lineTo(x+w*0.30,y+h*0.70);
  g.moveTo(x+w*0.70,y+h*0.70);g.lineTo(x+w,y+h*0.70);
  g.moveTo(x+w*0.30,y);g.lineTo(x+w*0.30,y+h*0.20);
  g.moveTo(x+w*0.70,y);g.lineTo(x+w*0.70,y+h*0.20);
  g.moveTo(x+w*0.30,y+h*0.80);g.lineTo(x+w*0.30,y+h);
  g.moveTo(x+w*0.70,y+h*0.80);g.lineTo(x+w*0.70,y+h);
