  g.strokeStyle='rgba(58,44,16,.7)';
  roundRect(g,x+w*0.30,y+h*0.20,w*0.40,h*0.60,2);g.stroke();
  g.strokeStyle='rgba(255,246,214,.30)';g.lineWidth=0.8;
  g.beginPath();g.moveTo(x,y+h*0.31);g.lineTo(x+w,y+h*0.31);g.stroke();
  g.restore();
