  g.translate(0,2.2);g.fillStyle='rgba(230,244,255,.22)';g.fill(LOGO);
  g.translate(0,-1.1);g.fillStyle='#c9d3de';g.fill(LOGO);
  g.restore();

  g.font='700 11px '+SANS;
  etchText(g,'CODEX',47,baseAt(g,20,11),2.2,null,'#cbd4de');

  g.font='9px '+MONO;
  etchText(g,'TITANIUM',BW-22,baseAt(g,21,9),2.6,'right','#8d949c');

  etchRule(g,22,41,BW-44);

  g.font='11px '+MONO;
  etchText(g,'MEMBER \\u00b7 SESSION 07',22,baseAt(g,50,11),1.98,null,'#98a0a9');

  /* chip and contactless */
  drawChip(g,22,80,48,37);
  drawContactless(g,86,98,26);

  /* the foil band */
  drawHologram(g,BW-96,76,74,46);
  g.font='700 7px '+MONO;
  etchText(g,'SECURE',BW-22,baseAt(g,126,7),1.8,'right','#7f868e');

  /* the account row, struck into the plate */
  g.font='700 20px '+MONO;
  embossText(g,'5412 7806',22,baseAt(g,252,20),1.4,null,'#b9c3cf');
  embossText(g,'2261 9034',22,baseAt(g,278,20),1.4,null,'#b9c3cf');

  g.font='8px '+MONO;
  etchText(g,'VALID THRU',22,baseAt(g,312,8),2.2,null,'#767d85');
  g.font='700 12px '+MONO;
  embossText(g,'08/29',22,baseAt(g,324,12),1.2,null,'#aab4c0');

  g.font='8px '+MONO;
  etchText(g,'TRACK',132,baseAt(g,312,8),2.2,null,'#767d85');
  g.font='700 12px '+MONO;
  embossText(g,'AGENTS',132,baseAt(g,324,12),1.2,null,'#aab4c0');

  g.font='8px '+MONO;
  etchText(g,'ISSUED',242,baseAt(g,312,8),2.2,null,'#767d85');
  g.font='700 12px '+MONO;
  embossText(g,'SG \\u00b7 26',242,baseAt(g,324,12),1.2,null,'#aab4c0');

