          if(s0){c.x[i]+=bx*bdiff*0.5;c.y[i]+=by*bdiff*0.5;}
          c.x[i+2]-=bx*bdiff*(s0?0.5:1);c.y[i+2]-=by*bdiff*(s0?0.5:1);
