    var f=(shade[i][2]+shade[i+2][2])*0.5;
    if(f<0.10)continue;
    var ax2=pts[i][0],ay2=pts[i][1],
        bx2=pts[i+2][0],by2=pts[i+2][1],
        ddx=bx2-ax2,ddy=by2-ay2,seglen=Math.hypot(ddx,ddy);
    if(seglen<0.4)continue;
    var hw=(Math.hypot(left[i][0]-right[i][0],left[i][1]-right[i][1])+
            Math.hypot(left[i+2][0]-right[i+2][0],left[i+2][1]-right[i+2][1]))*0.25;
